import 'dart:async';

import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:just_audio/just_audio.dart';

import '../../../core/logging/app_logger.dart';
import '../domain/cue_speaker.dart';
import '../domain/exercise_demo.dart';

final cueSpeakerProvider = Provider<CueSpeaker>((ref) {
  final speaker = ClipCueSpeaker(AudioPlayer.new);
  ref.onDispose(speaker.dispose);
  return speaker;
});

/// Plays recorded voice clips bundled with the app (generated by
/// tool/voice_cues/generate.py). It keeps its own players, separate from
/// recording playback, so a cue never interrupts or is logged as access to
/// a patient recording.
class ClipCueSpeaker implements CueSpeaker {
  ClipCueSpeaker(this._createPlayer);

  final AudioPlayer Function() _createPlayer;

  /// One preloaded player per cue, so a cue starts on time.
  final _players = <DemoCue, AudioPlayer>{};

  static String assetFor(DemoCue cue) => switch (cue) {
    DemoCue.breatheIn => 'assets/audio/cues/breathe_in.wav',
    DemoCue.breatheOut => 'assets/audio/cues/breathe_out.wav',
  };

  Future<AudioPlayer> _playerFor(DemoCue cue) async {
    if (_players[cue] case final player?) return player;
    final player = _createPlayer();
    _players[cue] = player;
    await player.setAsset(assetFor(cue));
    return player;
  }

  @override
  Future<void> speak(DemoCue cue) async {
    try {
      await stop();
      final player = await _playerFor(cue);
      await player.seek(Duration.zero);
      // Not awaited: play() completes only when the clip ends.
      unawaited(
        player.play().catchError((Object error, StackTrace stack) {
          AppLogger.error('Spoken cue playback failed', error, stack);
        }),
      );
    } on Object catch (error, stack) {
      // A player that failed to load is dropped so the next cue retries.
      await _players.remove(cue)?.dispose();
      AppLogger.error('Spoken cue failed', error, stack);
    }
  }

  @override
  Future<void> stop() async {
    for (final player in _players.values) {
      try {
        await player.pause();
      } on Object catch (error, stack) {
        AppLogger.error('Stopping spoken cue failed', error, stack);
      }
    }
  }

  Future<void> dispose() async {
    for (final player in _players.values) {
      await player.dispose();
    }
    _players.clear();
  }
}
